export class TrustlensApiError extends Error {
    constructor(message, code = "api_error", status = 500) {
        super(message);
        this.name = "TrustlensApiError";
        this.code = code;
        this.status = status;
    }
}
async function request(endpoint, options = {}) {
    const headers = new Headers(options.headers || {});
    if (!headers.has("Accept")) {
        headers.set("Accept", "application/json");
    }
    const response = await fetch(endpoint, {
        ...options,
        headers,
    });
    if (!response.ok) {
        let errorMessage = `Request failed with status ${response.status}`;
        let errorCode = "http_error";
        try {
            const errorBody = (await response.json());
            if (errorBody?.error?.message) {
                errorMessage = errorBody.error.message;
            }
            if (errorBody?.error?.code) {
                errorCode = errorBody.error.code;
            }
        }
        catch {
            // fallback to generic message
        }
        throw new TrustlensApiError(errorMessage, errorCode, response.status);
    }
    if (response.status === 204) {
        return null;
    }
    return (await response.json());
}
export const api = {
    async getHealth() {
        return request("/api/health");
    },
    async getCapabilities() {
        return request("/api/capabilities");
    },
    async getStats() {
        return request("/api/stats");
    },
    async getAnalyses(params = {}) {
        const searchParams = new URLSearchParams();
        if (params.limit !== undefined)
            searchParams.set("limit", String(params.limit));
        if (params.offset !== undefined)
            searchParams.set("offset", String(params.offset));
        if (params.status)
            searchParams.set("status", params.status);
        if (params.media_type)
            searchParams.set("media_type", params.media_type);
        if (params.q)
            searchParams.set("q", params.q);
        const query = searchParams.toString();
        const endpoint = query ? `/api/analyses?${query}` : "/api/analyses";
        return request(endpoint);
    },
    async getAnalysis(analysisId) {
        return request(`/api/analyses/${encodeURIComponent(analysisId)}`);
    },
    async getEvidence(analysisId) {
        return request(`/api/analyses/${encodeURIComponent(analysisId)}/evidence`);
    },
    async submitAnalysis(file, idempotencyKey) {
        const formData = new FormData();
        formData.append("file", file, file.name);
        const headers = {};
        if (idempotencyKey) {
            headers["Idempotency-Key"] = idempotencyKey;
        }
        else if (typeof crypto !== "undefined" && crypto.randomUUID) {
            headers["Idempotency-Key"] = crypto.randomUUID();
        }
        return request("/api/analyses", {
            method: "POST",
            headers,
            body: formData,
        });
    },
    async deleteAnalysis(analysisId) {
        await request(`/api/analyses/${encodeURIComponent(analysisId)}`, {
            method: "DELETE",
        });
    },
    getReportDownloadUrl(analysisId) {
        return `/api/analyses/${encodeURIComponent(analysisId)}/report`;
    },
};
